head.script:
scwin.initScreen = function() {
    widgetControler1.addWidgets({
        id: "wgc01_Calendar",
        title: "Calendar",
        src: "widgetContainer_Dynamic_SKT-306_(WSQ-944)_calendar.xml",
        scope: true,
        unitWidth: 3,
        unitHeight: 1,
        x: 1,
        y: 0
    });
    log = "Completed initScreen";
    //alert("Completed initScreen");
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 widgetSample.xml 을 실행한다.
    //1. Run widgetSample.xml in your browser.
    //Verify step 1. A Completed initScreen popup is created.
    WebSquare.wUnit.addCommand("assert", "log == 'Completed initScreen'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 확인버튼을 클릭한다.
    //2. Click the OK button.
    //Verify step 2. Calendar is displayed normally.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#widgetControler1_wgc01_Calendar').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }

    window.log = undefined;
    scwin.initScreen();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
